
import React from "react";

import "./deleteAlert.css"
import { CloseModal } from "./DialogHRM";





const DeleteAlert  = ({ data, confirm, lbl_p, lbl_span, colors }) => {

	const { modalID } = data;

	const handleClose =  (v) => {
		CloseModal({id:modalID})
    }
    
    const handleConfirm =  () => {
        confirm();
		handleClose();
	}

// 

	let colorPalette = colors || {
		"--alert-title-color":"var(--primary-light)",
		"--alert-desc-color":"var(--dark-800)",
	}

	let customS = {
		maxHeight: "40vh",
		minHeight:  "18vh",
		overflow: "auto",
		background: "var(--dark-800)",
		borderRadius: 13,
		padding: "10px 19px"
	}
	  
	let stylesC = Object.assign({},colorPalette, customS)

    return (
       
		<div style={stylesC}>
			<div className="_dsplFlx ">
				<p className="form_title lbl_title">
					{lbl_p}
				</p>
				<div className="flexSpace"/>
				
			</div>
			<div className="_dsplFlx lbl_desc">
				<span>
					{lbl_span}
				</span>
			</div>
			<div className="_dsplFlx " style={{padding:"15px 10px"}}>
				<div className="flexSpace"/>
				<p className="group_title addBtn" onClick={handleClose}>
					Cancelar
				</p>
				<p className="group_title addBtn red" onClick={handleConfirm}>
					Eliminar
				</p>
			</div>

		</div>
    )   
}

export default DeleteAlert;


